// src/pages/MeetingRoom.js

import {
  useLocation,
} from "react-router-dom";

import {
  useState,
  useEffect,
  useRef,
} from "react";

function MeetingRoom() {
  const location = useLocation();

  const roomTitle =
    location.state?.title ||
    "독서모임";

  const [input, setInput] =
    useState("");

  const [messages, setMessages] =
    useState([
      {
        user: "AI",
        type: "ai",
        text:
          "모임원들의 독후감과 기록을 먼저 정리했어요 ✨\n\n• 외로움과 연결감\n• 상실 이후의 성장\n• 잔잔하지만 깊은 감정선\n• 현실적인 인간 관계",
      },

      {
        user: "AI",
        type: "ai",
        text:
          "오늘은 가장 기억에 남았던 문장을 함께 이야기해볼게요 🙂",
      },

      {
        user: "민지",
        type: "other",
        color: "#FFB6C1",
        text:
          "저는 마지막 장면이 가장 슬펐어요.",
      },

      {
        user: "현우",
        type: "other",
        color: "#87CEEB",
        text:
          "문장이 진짜 고요해서 좋았어요.",
      },

      {
        user: "서연",
        type: "other",
        color: "#C3E88D",
        text:
          "와타나베 감정선이 너무 현실적이었어요.",
      },
    ]);

  const chatEndRef = useRef(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({
      behavior: "smooth",
    });
  }, [messages]);

  // =========================
  // 참가자 메시지 보내기
  // =========================

  const sendMessage = () => {
    if (!input.trim()) return;

    const myMessage = {
      user: "나",
      type: "me",
      text: input,
    };

    setMessages((prev) => [
      ...prev,
      myMessage,
    ]);

    setInput("");

    // 기존에 있던 AI 자동 응답은 삭제
    // 이제 AI는 자동으로 답변하지 않음
  };

  // =========================
  // AI 진행자 호출
  // =========================

  const requestAI = () => {
    // 현재까지의 대화 내용
    const conversation =
      messages
        .map(
          (message) =>
            `${message.user}: ${message.text}`
        )
        .join("\n");

    console.log(
      "AI에게 전달할 현재 대화:",
      conversation
    );

    // 현재는 더미 AI 응답
    // 나중에 이 부분을 백엔드 API 호출로 변경
    const aiReply = {
      user: "AI",
      type: "ai",
      text:
        "좋은 의견들이 나오고 있네요 🌿\n\n지금까지 이야기한 내용을 보면 인물의 감정과 상실에 대한 이야기가 많이 나온 것 같아요.\n\n여러분은 이 책에서 가장 공감했던 인물의 감정이 무엇이었나요?",
    };

    setMessages((prev) => [
      ...prev,
      aiReply,
    ]);
  };

  return (
    <div className="meeting-page">
      {/* =========================
          상단
      ========================= */}

      <div className="meeting-header">
        <div>
          <div className="meeting-room-name">
            📚 {roomTitle}
          </div>
        </div>
      </div>

      {/* =========================
          채팅
      ========================= */}

      <div className="meeting-chat-area">
        {messages.map((msg, index) => (
          <div
            key={index}
            className={`chat-row ${
              msg.type === "me"
                ? "right"
                : "left"
            }`}
          >
            {/* 프로필 */}

            {msg.type !== "me" && (
              <div
                className="chat-profile"
                style={{
                  background:
                    msg.type === "ai"
                      ? "#9bd44e"
                      : msg.color,
                }}
              >
                {msg.user[0]}
              </div>
            )}

            {/* 메시지 */}

            <div className="chat-content">
              {msg.type !== "me" && (
                <div className="chat-name">
                  {msg.user}
                </div>
              )}

              <div
                className={`chat-bubble ${
                  msg.type === "me"
                    ? "user-chat"
                    : msg.type === "ai"
                    ? "ai-chat"
                    : "other-chat"
                }`}
              >
                {msg.text}
              </div>
            </div>
          </div>
        ))}

        <div ref={chatEndRef}></div>
      </div>

      {/* =========================
          입력 영역
      ========================= */}

      <div className="meeting-input-wrap">
        <input
          value={input}
          onChange={(e) =>
            setInput(e.target.value)
          }
          placeholder="생각을 입력해보세요"
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              sendMessage();
            }
          }}
        />

        <button
          onClick={sendMessage}
        >
          전송
        </button>
      </div>

      {/* =========================
          AI 진행자 버튼
      ========================= */}

      <button
        className="ai-request-btn"
        onClick={requestAI}
      >
        ✨ AI 진행자
      </button>
    </div>
  );
}

export default MeetingRoom;
